package com.aditya.fefo.unit; import com.aditya.fefo.domain.*; import org.junit.jupiter.api.*; import java.time.*; import static org.junit.jupiter.api.Assertions.*; class BatchTest {Product p=new Product("S","P","");@Test void reserveMovesQuantities(){Batch b=new Batch(p,"B",LocalDate.now().plusDays(1),10);b.reserve(4);assertEquals(6,b.getAvailableQuantity());assertEquals(4,b.getReservedQuantity());}@Test void releaseReturnsStock(){Batch b=new Batch(p,"B",LocalDate.now().plusDays(1),10);b.reserve(4);b.release(4);assertEquals(10,b.getAvailableQuantity());assertEquals(0,b.getReservedQuantity());}@Test void confirmConsumesHold(){Batch b=new Batch(p,"B",LocalDate.now().plusDays(1),10);b.reserve(4);b.confirm(4);assertEquals(6,b.getAvailableQuantity());assertEquals(0,b.getReservedQuantity());}}
